SELECT ?jurisdiction (COUNT(?entity) AS ?count)
WHERE {
  ?entity a gleif-L1:RegisteredEntity ;
            gleif-base:hasRegistrationStatus gleif-L1:LAPSED ;
            gleif-base:hasLegalJurisdiction ?jurisdiction .
}
GROUP BY ?jurisdiction
ORDER BY DESC(?count)
LIMIT 3

